const seen = $getWorkflowStaticData('global');
seen.ids = seen.ids || [];
const out = [];
for (const r of ($json.result?.reviews || [])) {
  if (!seen.ids.includes(r.time)) { seen.ids.push(r.time); out.push({ json: { Time: new Date(r.time*1000).toISOString(), Author: r.author_name, Rating: r.rating, Text: r.text || '', rating_total: $json.result.rating } }); }
}
seen.ids = seen.ids.slice(-100);
return out;
